//! Sharded teacher-data generation orchestration.
//!
//! Builds many small shard files in parallel, each generated by its own Gikou
//! child process. Shards are independent deterministic units (content fixed by
//! their seed), so any worker can produce any shard and the run is resumable.
//!
//! Robustness model (mirrors the NOCCA write-ahead approach):
//!   1. generate the shard fully in memory,
//!   2. write `shard.hcpe.tmp` / `shard.expected.tsv.tmp` and atomically rename
//!      them into place (the shard file exists only when complete),
//!   3. *then* mark the shard `done` in the manifest and persist the manifest
//!      atomically.
//! A crash between (2) and (3) leaves a complete shard file but no `done` flag,
//! so resume simply regenerates it (identical bytes). A crash during (1)/(2)
//! leaves only a `.tmp`, which is ignored and cleaned up.

use std::collections::VecDeque;
use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

use shogi_core::Color;

use super::gikou::{GikouEngine, GikouError, GikouOptions};
use super::hcpe::{HcpeEntry, HcpeGameResult, HCPE_ENTRY_SIZE};
use super::manifest::{GenMeta, Manifest, ShardRecord, SCHEMA_VERSION};

fn opposite_color(c: Color) -> Color {
    match c {
        Color::Black => Color::White,
        Color::White => Color::Black,
    }
}

use crate::{find_legal_move, hex, initial_position, position_to_sfen, sfen_core, SplitMix64};

#[derive(Debug, Clone)]
pub struct GenConfig {
    pub gikou_path: PathBuf,
    pub out_dir: PathBuf,
    pub target_positions: usize,
    pub shard_size: usize,
    pub workers: usize,
    pub depth: usize,
    pub random_plies: usize,
    pub max_plies: usize,
    pub base_seed: u64,
    pub timeout: Duration,
    pub own_book: bool,
    pub max_shard_retries: usize,
}

#[derive(Debug, Clone)]
struct ShardPlan {
    index: usize,
    seed: u64,
    target_count: usize,
    file: String,
    hcpe_path: PathBuf,
    expected_path: PathBuf,
}

struct ShardOutput {
    hcpe_bytes: Vec<u8>,
    expected_tsv: String,
    count: usize,
    games: usize,
    mate_cutoffs: usize,
    resign_cutoffs: usize,
    max_ply_cutoffs: usize,
    crash_cutoffs: usize,
    timeouts: usize,
    engine_restarts: usize,
    eval_min: i32,
    eval_max: i32,
}

#[derive(Debug)]
enum ShardGenError {
    Gikou(GikouError),
    IllegalBestmove { sfen: String, bestmove: String },
    Encode(String),
    TooManyGames { games: usize, written: usize },
}

impl ShardGenError {
    fn requires_restart(&self) -> bool {
        matches!(self, Self::Gikou(err) if err.requires_restart())
    }

    fn is_timeout(&self) -> bool {
        matches!(self, Self::Gikou(GikouError::Timeout { .. }))
    }
}

impl std::fmt::Display for ShardGenError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Gikou(err) => write!(f, "gikou error: {err}"),
            Self::IllegalBestmove { sfen, bestmove } => {
                write!(f, "illegal bestmove {bestmove} for sfen {sfen}")
            }
            Self::Encode(message) => write!(f, "encode error: {message}"),
            Self::TooManyGames { games, written } => {
                write!(f, "too many games ({games}) without filling shard ({written})")
            }
        }
    }
}

pub fn run_gen_teacher(config: GenConfig) -> Result<(), String> {
    if config.target_positions == 0 {
        return Err("target_positions must be >= 1".to_string());
    }
    if config.shard_size == 0 {
        return Err("shard_size must be >= 1".to_string());
    }
    if config.workers == 0 {
        return Err("workers must be >= 1".to_string());
    }
    if config.depth == 0 {
        return Err("depth must be >= 1".to_string());
    }
    if config.random_plies >= config.max_plies {
        return Err("random_plies must be smaller than max_plies".to_string());
    }

    fs::create_dir_all(&config.out_dir)
        .map_err(|err| format!("failed to create out_dir: {err}"))?;
    cleanup_stale_tmp(&config.out_dir);

    let plans = build_plans(&config);

    // Load or create the manifest, reconciling `done` flags against actual files.
    let manifest = match Manifest::path_in(&config.out_dir).exists() {
        true => {
            let mut loaded = Manifest::load(&config.out_dir)?;
            check_meta_compatible(&config, &loaded.meta)?;
            reconcile_done_flags(&config, &plans, &mut loaded);
            loaded
        }
        false => {
            let manifest = fresh_manifest(&config, &plans);
            manifest.save_atomic(&config.out_dir)?;
            manifest
        }
    };

    let pending: Vec<usize> = manifest
        .shards
        .iter()
        .filter(|shard| !shard.done)
        .map(|shard| shard.index)
        .collect();
    let already_done = plans.len() - pending.len();

    eprintln!(
        "gen-teacher: target={} shard_size={} shards={} workers={} depth={} timeout={}s",
        config.target_positions,
        config.shard_size,
        plans.len(),
        config.workers,
        config.depth,
        config.timeout.as_secs(),
    );
    eprintln!(
        "gen-teacher: resume state: {already_done} shard(s) already done, {} pending",
        pending.len()
    );

    let started = Instant::now();
    let config = Arc::new(config);
    let plans = Arc::new(plans);
    let manifest = Arc::new(Mutex::new(manifest));
    let queue = Arc::new(Mutex::new(pending.into_iter().collect::<VecDeque<usize>>()));
    let failures = Arc::new(Mutex::new(Vec::<(usize, String)>::new()));
    let total_shards = plans.len();

    let workers = config.workers.min(total_shards.max(1));
    let mut handles = Vec::with_capacity(workers);
    for worker_id in 0..workers {
        let config = Arc::clone(&config);
        let plans = Arc::clone(&plans);
        let manifest = Arc::clone(&manifest);
        let queue = Arc::clone(&queue);
        let failures = Arc::clone(&failures);
        handles.push(thread::spawn(move || {
            worker_loop(
                worker_id,
                &config,
                &plans,
                &manifest,
                &queue,
                &failures,
                total_shards,
            );
        }));
    }
    for handle in handles {
        let _ = handle.join();
    }

    let elapsed = started.elapsed();

    // Final atomic persist (the incremental saves already did this, but be safe).
    let manifest = Arc::try_unwrap(manifest)
        .map(Mutex::into_inner)
        .map_err(|_| "manifest still shared".to_string())?
        .map_err(|err| format!("manifest mutex poisoned: {err}"))?;
    manifest.save_atomic(&config.out_dir)?;

    let failures = Arc::try_unwrap(failures)
        .map(Mutex::into_inner)
        .map_err(|_| "failures still shared".to_string())?
        .map_err(|err| format!("failures mutex poisoned: {err}"))?;

    print_summary(&config, &manifest, &failures, elapsed);

    if !failures.is_empty() {
        return Err(format!(
            "{} shard(s) failed to generate; rerun the same command to resume/retry",
            failures.len()
        ));
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn worker_loop(
    worker_id: usize,
    config: &GenConfig,
    plans: &[ShardPlan],
    manifest: &Mutex<Manifest>,
    queue: &Mutex<VecDeque<usize>>,
    failures: &Mutex<Vec<(usize, String)>>,
    total_shards: usize,
) {
    loop {
        let Some(index) = pop_index(queue) else {
            break;
        };
        let plan = &plans[index];

        let shard_started = Instant::now();
        let mut attempt_timeouts = 0usize;
        let mut attempt_restarts = 0usize;

        // Each shard is generated by a *fresh* Gikou process. Gikou keeps internal
        // state that no USI command (usinewgame/isready) resets, so a fresh process
        // is the only way to make a shard's content depend solely on its seed —
        // i.e. reproducible regardless of worker count or completion order.
        let outcome: Result<ShardOutput, String> = 'attempts: {
            for attempt in 0..=config.max_shard_retries {
                let mut engine = match start_engine(config) {
                    Ok(engine) => engine,
                    Err(err) => {
                        if attempt < config.max_shard_retries {
                            attempt_restarts += 1;
                            eprintln!(
                                "[worker {worker_id}] shard {index}: start failed: {err} (retry {}/{})",
                                attempt + 1,
                                config.max_shard_retries
                            );
                            continue;
                        }
                        break 'attempts Err(format!("failed to start Gikou: {err}"));
                    }
                };
                if attempt > 0 {
                    attempt_restarts += 1;
                }
                match generate_shard(&mut engine, config, plan.seed, plan.target_count) {
                    Ok(output) => break 'attempts Ok(output),
                    Err(err) if err.requires_restart() && attempt < config.max_shard_retries => {
                        if err.is_timeout() {
                            attempt_timeouts += 1;
                        }
                        eprintln!(
                            "[worker {worker_id}] shard {index}: {err} -> fresh Gikou (retry {}/{})",
                            attempt + 1,
                            config.max_shard_retries
                        );
                        // engine dropped here (killed); next attempt spawns a fresh one
                    }
                    Err(err) => break 'attempts Err(err.to_string()),
                }
            }
            Err("retries exhausted".to_string())
        };

        match outcome {
            Ok(output) => {
                if let Err(err) = commit_shard(plan, &output) {
                    record_failure(failures, index, format!("commit failed: {err}"));
                    eprintln!("[worker {worker_id}] shard {index}: commit failed: {err}");
                    continue;
                }
                let elapsed_ms = shard_started.elapsed().as_secs_f64() * 1000.0;
                let done_count = update_done(
                    manifest,
                    &config.out_dir,
                    index,
                    &output,
                    attempt_timeouts,
                    attempt_restarts,
                    elapsed_ms,
                );
                match done_count {
                    Ok(done_count) => {
                        eprintln!(
                            "[worker {worker_id}] shard {index} done ({done_count}/{total_shards}) \
                             count={} games={} mate={} resign={} maxply={} crash={} timeouts={} restarts={} \
                             eval=[{}..{}] {:.1}s",
                            output.count,
                            output.games,
                            output.mate_cutoffs,
                            output.resign_cutoffs,
                            output.max_ply_cutoffs,
                            output.crash_cutoffs,
                            output.timeouts + attempt_timeouts,
                            output.engine_restarts + attempt_restarts,
                            output.eval_min,
                            output.eval_max,
                            elapsed_ms / 1000.0,
                        );
                    }
                    Err(err) => {
                        record_failure(failures, index, format!("manifest update failed: {err}"));
                        eprintln!("[worker {worker_id}] shard {index}: manifest update failed: {err}");
                    }
                }
            }
            Err(err) => {
                record_failure(failures, index, err.to_string());
                eprintln!("[worker {worker_id}] shard {index}: FAILED: {err}");
            }
        }
    }
}

fn pop_index(queue: &Mutex<VecDeque<usize>>) -> Option<usize> {
    queue.lock().ok().and_then(|mut q| q.pop_front())
}

fn record_failure(failures: &Mutex<Vec<(usize, String)>>, index: usize, message: String) {
    if let Ok(mut f) = failures.lock() {
        f.push((index, message));
    }
}

fn start_engine(config: &GenConfig) -> Result<GikouEngine, GikouError> {
    let mut options = GikouOptions::new(&config.gikou_path, config.own_book, 1);
    // Allow the handshake (param load) plenty of time, especially under load.
    options.handshake_timeout = Duration::from_secs(120);
    GikouEngine::with_options(options)
}

fn update_done(
    manifest: &Mutex<Manifest>,
    out_dir: &Path,
    index: usize,
    output: &ShardOutput,
    attempt_timeouts: usize,
    attempt_restarts: usize,
    elapsed_ms: f64,
) -> Result<usize, String> {
    let mut guard = manifest
        .lock()
        .map_err(|err| format!("manifest mutex poisoned: {err}"))?;
    if let Some(shard) = guard.shards.iter_mut().find(|s| s.index == index) {
        shard.count = output.count;
        shard.done = true;
        shard.games = output.games;
        shard.mate_cutoffs = output.mate_cutoffs;
        shard.resign_cutoffs = output.resign_cutoffs;
        shard.max_ply_cutoffs = output.max_ply_cutoffs;
        shard.crash_cutoffs = output.crash_cutoffs;
        shard.timeouts = output.timeouts + attempt_timeouts;
        shard.engine_restarts = output.engine_restarts + attempt_restarts;
        shard.elapsed_ms = elapsed_ms;
        shard.eval_min = output.eval_min;
        shard.eval_max = output.eval_max;
    }
    guard.save_atomic(out_dir)?;
    Ok(guard.shards.iter().filter(|s| s.done).count())
}

fn build_plans(config: &GenConfig) -> Vec<ShardPlan> {
    let shard_count = config.target_positions.div_ceil(config.shard_size);
    let mut plans = Vec::with_capacity(shard_count);
    let mut remaining = config.target_positions;
    for index in 0..shard_count {
        let target_count = remaining.min(config.shard_size);
        remaining -= target_count;
        let file = format!("shard_{index:04}.hcpe");
        let hcpe_path = config.out_dir.join(&file);
        let expected_path = config.out_dir.join(format!("shard_{index:04}.expected.tsv"));
        plans.push(ShardPlan {
            index,
            seed: config.base_seed.wrapping_add(index as u64),
            target_count,
            file,
            hcpe_path,
            expected_path,
        });
    }
    plans
}

fn fresh_manifest(config: &GenConfig, plans: &[ShardPlan]) -> Manifest {
    let meta = GenMeta {
        schema_version: SCHEMA_VERSION,
        gikou_path: config.gikou_path.to_string_lossy().into_owned(),
        depth: config.depth,
        random_plies: config.random_plies,
        max_plies: config.max_plies,
        base_seed: config.base_seed,
        shard_size: config.shard_size,
        target_positions: config.target_positions,
        own_book: config.own_book,
        threads_per_engine: 1,
        timeout_ms: config.timeout.as_millis() as u64,
        hcpe_entry_size: HCPE_ENTRY_SIZE,
        binbo_git_commit: git_short_commit(),
        created_at: now_iso8601(),
    };
    let shards = plans
        .iter()
        .map(|plan| ShardRecord::pending(plan.index, plan.file.clone(), plan.seed, plan.target_count))
        .collect();
    Manifest { meta, shards }
}

fn check_meta_compatible(config: &GenConfig, meta: &GenMeta) -> Result<(), String> {
    let mismatches = [
        ("target_positions", meta.target_positions, config.target_positions),
        ("shard_size", meta.shard_size, config.shard_size),
        ("depth", meta.depth, config.depth),
        ("random_plies", meta.random_plies, config.random_plies),
        ("max_plies", meta.max_plies, config.max_plies),
    ];
    for (name, found, requested) in mismatches {
        if found != requested {
            return Err(format!(
                "manifest {name}={found} differs from requested {requested}; use a fresh out_dir or matching args"
            ));
        }
    }
    if meta.base_seed != config.base_seed {
        return Err(format!(
            "manifest base_seed={} differs from requested {}; use a fresh out_dir or matching args",
            meta.base_seed, config.base_seed
        ));
    }
    if meta.own_book != config.own_book {
        return Err(format!(
            "manifest own_book={} differs from requested {}",
            meta.own_book, config.own_book
        ));
    }
    Ok(())
}

/// A shard claimed `done` is only trusted if its file exists with the exact
/// expected byte length. Otherwise it is reset to pending so it is regenerated.
fn reconcile_done_flags(config: &GenConfig, plans: &[ShardPlan], manifest: &mut Manifest) {
    for shard in &mut manifest.shards {
        if !shard.done {
            continue;
        }
        let Some(plan) = plans.get(shard.index) else {
            shard.done = false;
            continue;
        };
        let expected_len = (shard.count * HCPE_ENTRY_SIZE) as u64;
        let ok = shard.count == plan.target_count
            && fs::metadata(&plan.hcpe_path)
                .map(|meta| meta.len() == expected_len)
                .unwrap_or(false);
        if !ok {
            eprintln!(
                "gen-teacher: shard {} marked done but file missing/short -> regenerating",
                shard.index
            );
            shard.done = false;
        }
    }
    let _ = config;
}

fn generate_shard(
    engine: &mut GikouEngine,
    config: &GenConfig,
    seed: u64,
    target_count: usize,
) -> Result<ShardOutput, ShardGenError> {
    let mut rng = SplitMix64::new(seed);
    let mut hcpe_bytes = Vec::with_capacity(target_count * HCPE_ENTRY_SIZE);
    let mut expected = String::new();
    expected.push_str(
        "index\tname\tsfen_core\teval\tbestmove_usi\tbestMove16\tgameResult\tdummy\thcp_hex\n",
    );

    let mut written = 0usize;
    let mut games = 0usize;
    let mut mate_cutoffs = 0usize;
    let mut resign_cutoffs = 0usize;
    let mut max_ply_cutoffs = 0usize;
    let mut crash_cutoffs = 0usize;
    let mut timeouts = 0usize;
    let mut engine_restarts = 0usize;
    let mut logged_crashes = 0usize;
    let mut eval_min = i32::MAX;
    let mut eval_max = i32::MIN;
    let max_games = target_count.saturating_mul(50).max(100);

    while written < target_count {
        if games >= max_games {
            return Err(ShardGenError::TooManyGames { games, written });
        }
        games += 1;
        let mut pos = initial_position();

        for _ in 0..config.random_plies {
            let moves = pos.legal_moves();
            if moves.is_empty() {
                break;
            }
            let mv = moves[rng.gen_index(moves.len())];
            pos.do_move(mv);
        }

        // Buffer the game's positions; the result (WDL) is only known at the
        // terminal, then back-filled into every position's `gameResult` so the
        // student can learn from the actual outcome, not just the cp eval.
        let mut game_buf: Vec<(HcpeEntry, String, i16, String, usize)> = Vec::new();
        let mut winner: Option<Color> = None; // None => draw / unknown (max_ply, crash)
        let mut hit_max_plies = true;
        for _ply in config.random_plies..config.max_plies {
            if written + game_buf.len() >= target_count {
                hit_max_plies = false;
                break; // shard full; flush the partial game below (no decisive end)
            }
            let sfen = position_to_sfen(&pos);
            let stm = pos.side_to_move();
            let analysis = match engine.analyze_sfen(&sfen, config.depth, config.timeout) {
                Ok(analysis) => analysis,
                Err(GikouError::MateScore(score)) => {
                    mate_cutoffs += 1;
                    // score>0: side to move mates (wins); score<=0: it is mated.
                    winner = Some(if score > 0 { stm } else { opposite_color(stm) });
                    hit_max_plies = false;
                    break;
                }
                // Gikou hung (timeout) or crashed (EOF) on this position. Abandon
                // this game, respawn a fresh engine, and keep filling the shard.
                // The trigger is deterministic, so the shard stays reproducible.
                Err(err) if err.requires_restart() => {
                    if matches!(err, GikouError::Timeout { .. }) {
                        timeouts += 1;
                    } else {
                        crash_cutoffs += 1;
                    }
                    if logged_crashes < 3 {
                        eprintln!(
                            "shard(seed={seed}): gikou {err}; abandoning game, sfen={sfen}"
                        );
                        logged_crashes += 1;
                    }
                    engine.restart().map_err(ShardGenError::Gikou)?;
                    engine_restarts += 1;
                    hit_max_plies = false;
                    break; // unknown result -> draw label
                }
                Err(err) => return Err(ShardGenError::Gikou(err)),
            };
            if analysis.bestmove == "resign" {
                resign_cutoffs += 1;
                winner = Some(opposite_color(stm)); // side to move resigns -> loses
                hit_max_plies = false;
                break;
            }
            if analysis.bestmove == "win" {
                resign_cutoffs += 1;
                winner = Some(stm); // side to move declares a win
                hit_max_plies = false;
                break;
            }
            let best_move = find_legal_move(&pos, &analysis.bestmove).ok_or_else(|| {
                ShardGenError::IllegalBestmove {
                    sfen: sfen.clone(),
                    bestmove: analysis.bestmove.clone(),
                }
            })?;
            let entry =
                HcpeEntry::from_position(&pos, analysis.eval_cp, best_move, HcpeGameResult::Draw)
                    .map_err(|err| ShardGenError::Encode(err.to_string()))?;
            let eval = analysis.eval_cp as i32;
            eval_min = eval_min.min(eval);
            eval_max = eval_max.max(eval);
            game_buf.push((
                entry,
                sfen_core(&sfen).to_string(),
                analysis.eval_cp,
                analysis.bestmove,
                _ply,
            ));
            pos.do_move(best_move);
        }

        if hit_max_plies {
            max_ply_cutoffs += 1;
        }

        // Resolve the absolute game result and write every buffered position with it.
        let game_result = match winner {
            Some(Color::Black) => HcpeGameResult::BlackWin,
            Some(Color::White) => HcpeGameResult::WhiteWin,
            None => HcpeGameResult::Draw,
        };
        for (mut entry, score_core, eval_cp, bestmove, ply) in game_buf {
            entry.game_result = game_result;
            hcpe_bytes.extend_from_slice(&entry.encode());
            writeln!(
                expected,
                "{}\tg{}_p{}\t{}\t{}\t{}\t{}\t{}\t0\t{}",
                written,
                games,
                ply,
                score_core,
                eval_cp,
                bestmove,
                entry.best_move16,
                game_result as i8,
                hex(&entry.hcp)
            )
            .expect("writing to String never fails");
            written += 1;
        }
    }

    Ok(ShardOutput {
        hcpe_bytes,
        expected_tsv: expected,
        count: written,
        games,
        mate_cutoffs,
        resign_cutoffs,
        max_ply_cutoffs,
        crash_cutoffs,
        timeouts,
        engine_restarts,
        eval_min: if eval_min == i32::MAX { 0 } else { eval_min },
        eval_max: if eval_max == i32::MIN { 0 } else { eval_max },
    })
}

fn commit_shard(plan: &ShardPlan, output: &ShardOutput) -> Result<(), String> {
    write_atomic(&plan.hcpe_path, &output.hcpe_bytes)?;
    write_atomic(&plan.expected_path, output.expected_tsv.as_bytes())?;
    Ok(())
}

fn write_atomic(path: &Path, bytes: &[u8]) -> Result<(), String> {
    let tmp = tmp_path(path);
    fs::write(&tmp, bytes).map_err(|err| format!("write {}: {err}", tmp.display()))?;
    fs::rename(&tmp, path).map_err(|err| format!("rename into {}: {err}", path.display()))?;
    Ok(())
}

fn tmp_path(path: &Path) -> PathBuf {
    let mut name = path.file_name().unwrap_or_default().to_os_string();
    name.push(".tmp");
    path.with_file_name(name)
}

fn cleanup_stale_tmp(dir: &Path) {
    let Ok(entries) = fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.extension().map(|ext| ext == "tmp").unwrap_or(false) {
            let _ = fs::remove_file(&path);
        }
    }
}

fn print_summary(
    config: &GenConfig,
    manifest: &Manifest,
    failures: &[(usize, String)],
    elapsed: Duration,
) {
    let done: Vec<&ShardRecord> = manifest.shards.iter().filter(|s| s.done).collect();
    let total_positions: usize = done.iter().map(|s| s.count).sum();
    let total_games: usize = done.iter().map(|s| s.games).sum();
    let total_mate: usize = done.iter().map(|s| s.mate_cutoffs).sum();
    let total_resign: usize = done.iter().map(|s| s.resign_cutoffs).sum();
    let total_maxply: usize = done.iter().map(|s| s.max_ply_cutoffs).sum();
    let total_crash: usize = done.iter().map(|s| s.crash_cutoffs).sum();
    let total_timeouts: usize = done.iter().map(|s| s.timeouts).sum();
    let total_restarts: usize = done.iter().map(|s| s.engine_restarts).sum();
    let eval_min = done.iter().map(|s| s.eval_min).min().unwrap_or(0);
    let eval_max = done.iter().map(|s| s.eval_max).max().unwrap_or(0);

    let elapsed_ms = elapsed.as_secs_f64() * 1000.0;
    let avg_ms = if total_positions > 0 {
        elapsed_ms / total_positions as f64
    } else {
        0.0
    };
    // Single-process estimate for the same target, from Task 015 (~4.07 ms/pos).
    let serial_estimate_hours = 4.07 * config.target_positions as f64 / 1000.0 / 3600.0;
    let speedup = if avg_ms > 0.0 { 4.07 / avg_ms } else { 0.0 };

    println!("out_dir={}", config.out_dir.display());
    println!("manifest={}", Manifest::path_in(&config.out_dir).display());
    println!("target_positions={}", config.target_positions);
    println!("total_positions={total_positions}");
    println!("shards_total={}", manifest.shards.len());
    println!("shards_done={}", done.len());
    println!("shards_failed={}", failures.len());
    println!("workers={}", config.workers);
    println!("depth={}", config.depth);
    println!("total_games={total_games}");
    println!("mate_cutoffs={total_mate}");
    println!("resign_cutoffs={total_resign}");
    println!("max_ply_cutoffs={total_maxply}");
    println!("crash_cutoffs={total_crash}");
    println!("timeouts={total_timeouts}");
    println!("engine_restarts={total_restarts}");
    println!("eval_min={eval_min}");
    println!("eval_max={eval_max}");
    println!("file_bytes_per_position={HCPE_ENTRY_SIZE}");
    println!("elapsed_ms={elapsed_ms:.3}");
    println!("elapsed_min={:.3}", elapsed_ms / 1000.0 / 60.0);
    println!("avg_ms_per_position={avg_ms:.4}");
    println!("serial_estimate_hours={serial_estimate_hours:.3}");
    println!("parallel_speedup_vs_serial={speedup:.2}");
    if failures.is_empty() {
        println!("status=ok");
    } else {
        println!("status=incomplete");
        for (index, message) in failures {
            println!("failed_shard index={index} reason={message}");
        }
    }
}

fn git_short_commit() -> String {
    Command::new("git")
        .args(["rev-parse", "--short", "HEAD"])
        .output()
        .ok()
        .filter(|out| out.status.success())
        .map(|out| String::from_utf8_lossy(&out.stdout).trim().to_string())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "unknown".to_string())
}

fn now_iso8601() -> String {
    Command::new("date")
        .args(["-u", "+%Y-%m-%dT%H:%M:%SZ"])
        .output()
        .ok()
        .filter(|out| out.status.success())
        .map(|out| String::from_utf8_lossy(&out.stdout).trim().to_string())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "unknown".to_string())
}
